// 未完了タスクを走査し、リマインド・エスカレーションの対象を選ぶ。
// メンバー(state/members)と PC(state/pcs)の両方を見る。
//
// verify: api のタスクは、実サービス(NetBox)の状態を見て自動的に閉じる。
// これにより「機器情報更新フォームを使っても NetBox を直接編集しても
// 同じように完了になる」= 更新経路を強制しない、が成立する。
// blocking: false のタスク(PC の IP 登録)はリマインドするがエスカレーションしない。
// 設計: docs/design/02-pc-register.md / 04-notification-abstraction.md

const members = $('台帳を読む').all().map((i) => i.json).filter((m) => m.desired);
const pcs = $('PC台帳を読む').all().map((i) => i.json).filter((p) => p.state);

// NetBox の実態(device id -> 実際の値)
const nb = {};
try {
  const res = $input.first()?.json ?? {};
  for (const dev of (res.results ?? [])) {
    nb[dev.id] = {
      name: dev.name,
      assetTag: dev.asset_tag,
      provisional: (dev.tags ?? []).some((t) => t.slug === 'provisional'),
      ip: dev.primary_ip4?.address ?? null,
    };
  }
} catch (e) { /* NetBox が落ちていても他の処理は続ける */ }

const intervalDays = Number($env.REMIND_INTERVAL_DAYS ?? 3);
const maxRemind = Number($env.REMIND_MAX ?? 3);
const adminTo = String($env.ADMIN_EMAILS ?? '').split(',').map((s) => s.trim()).filter(Boolean);

const now = new Date();
const days = (a, b) => Math.floor((a - b) / 86400000);

const notices = [];
const patches = [];

// --- 事後検証: NetBox を見て verify: api のタスクを閉じられるか判定する ---
const verifyDone = (pc, task) => {
  const dev = nb[pc.state?.netbox_device_id];
  if (!dev) return null;                       // NetBox を見られない場合は判断しない
  if (task.kind === 'pc-official-info') return dev.provisional === false;
  if (task.kind === 'pc-ip') return Boolean(dev.ip);
  return null;
};

const processTasks = (rec, label, opts) => {
  const tasks = Array.isArray(rec.state?.tasks) ? rec.state.tasks : [];
  let changed = false;

  const next = tasks.map((t) => {
    if (t.status !== 'open') return t;

    // 実サービス側で満たされていれば、人の報告を待たずに閉じる
    if (t.verify === 'api') {
      const done = opts.verify ? opts.verify(rec, t) : null;
      if (done === true) {
        changed = true;
        return { ...t, status: 'done', completed_at: now.toISOString(), token: null,
                 complete_url: null, closed_by: '事後検証' };
      }
    }

    const overdue = t.due ? days(now, new Date(t.due)) > 0 : false;
    const last = t.last_reminded_at ? new Date(t.last_reminded_at) : null;
    if (last && days(now, last) < intervalDays) return t;

    const count = Number(t.remind_count ?? 0);
    const blocking = t.blocking !== false;

    if (overdue && count >= maxRemind && blocking) {
      notices.push({
        to: adminTo, level: 'escalation',
        subject: `未完了のまま期限を大きく超過: ${t.subject}`,
        body: [
          `対象: ${label}`,
          `タスク: ${t.subject}`,
          `担当: ${t.assignee}`,
          `期限: ${t.due}(${days(now, new Date(t.due))} 日超過)`,
          `リマインド: ${count} 回送信済み`,
          '',
          '担当者が対応できない状態の可能性があります。管理者の介入が必要です。',
        ].join('\n'),
      });
      changed = true;
      return { ...t, status: 'escalated', escalated_at: now.toISOString() };
    }

    if (count < maxRemind || !blocking) {
      notices.push({
        to: [t.assignee], level: overdue ? 'warn' : 'info',
        subject: overdue ? `期限超過: ${t.subject}` : `未完了のお知らせ: ${t.subject}`,
        body: [
          `対象: ${label}`,
          t.steps ? `手順: ${t.steps}` : '',
          t.due ? `期限: ${t.due}${overdue ? '(超過しています)' : ''}` : '期限: 指定なし',
          '',
          t.complete_url ? `完了したらこちらを開いてください: ${t.complete_url}` : '',
          blocking ? '' : '※ このタスクは必須ではありませんが、記録のためご対応ください。',
        ].filter(Boolean).join('\n'),
      });
      changed = true;
      return { ...t, remind_count: count + 1, last_reminded_at: now.toISOString() };
    }

    return t;
  });

  return { changed, next };
};

// --- メンバー ---
for (const m of members) {
  const d = m.desired;
  const { changed, next } = processTasks(m, `${d.name ?? m.id} (${m.id})`, {});
  if (changed) {
    patches.push({ kind: 'members', id: m.id, patch: { tasks: next }, reason: 'リマインド状況を更新' });
  }

  // 協力会社メンバーの契約期限。期限を過ぎてもアクセスは自動遮断しない
  // (fail-open を意図的に受容。08 参照)。
  if (d.status === 'active' && d.contract_until && d.sponsor) {
    const remaining = -days(now, new Date(d.contract_until));
    if (remaining <= 30) {
      notices.push({
        to: [d.sponsor], level: remaining < 0 ? 'escalation' : 'warn',
        subject: remaining < 0
          ? `契約期限を超過しています: ${d.name ?? m.id}`
          : `契約期限が近づいています(残り ${remaining} 日): ${d.name ?? m.id}`,
        body: [
          `対象: ${d.name ?? m.id} (${d.email}) / ${d.affiliation}`,
          `契約期限: ${d.contract_until}`,
          '',
          '継続する場合は台帳の contract_until を更新する PR を、',
          '終了する場合は status: left にする PR を出してください。',
          remaining < 0 ? '\n※ 期限を過ぎてもアクセスは自動停止しません。対応が必要です。' : '',
        ].filter(Boolean).join('\n'),
      });
    }
  }
}

// --- PC ---
for (const pc of pcs) {
  const st = pc.state ?? {};
  const name = st.computer_name?.value ?? pc.id;
  const { changed, next } = processTasks(pc, `${name} (${pc.id})`, { verify: verifyDone });

  const patch = {};
  if (changed) patch.tasks = next;

  // NetBox の値を state に追随させる(直接編集された場合の取り込み)
  const dev = nb[st.netbox_device_id];
  if (dev) {
    if (dev.ip && st.ip_address !== dev.ip) patch.ip_address = dev.ip;
    if (dev.provisional === false && (st.computer_name?.provisional || st.asset_no?.provisional)) {
      patch.computer_name = { value: dev.name, provisional: false };
      patch.asset_no = { value: dev.assetTag, provisional: false };
    }
  }

  // blocking タスクが片付いたら active にする(blocking: false は妨げない)
  const openBlocking = next.filter((t) => t.status === 'open' && t.blocking !== false).length;
  if (openBlocking === 0 && st.status && st.status !== 'active') patch.status = 'active';

  if (Object.keys(patch).length) {
    patches.push({ kind: 'pcs', id: pc.id, patch, reason: 'タスクと実態を反映' });
  }
}

if (notices.length === 0) {
  return [{ json: { __nonotice: true, patches } }];
}
return notices.map((n) => ({ json: { ...n, __patches: patches } }));

// リマインド回数などの更新を state に書き戻す入力を作る。
let patches = [];
try {
  patches = $('リマインド対象を選ぶ').first().json.__patches ?? $('リマインド対象を選ぶ').first().json.patches ?? [];
} catch (e) { patches = []; }
return patches.length ? patches.map((json) => ({ json })) : [{ json: { __nowrite: true } }];

// 実行サマリ。
let notices = [];
try { notices = $('リマインド対象を選ぶ').all().map((i) => i.json).filter((n) => !n.__nonotice); } catch (e) {}

return [{ json: {
  reminders: notices.filter((n) => n.level !== 'escalation').map((n) => `${n.to?.join(',')} — ${n.subject}`),
  escalations: notices.filter((n) => n.level === 'escalation').map((n) => `${n.to?.join(',')} — ${n.subject}`),
  updated: $input.all().map((i) => i.json).filter((w) => w?.ok).map((w) => w.path),
}}];
